 var runner=Run();while(true){object next=null;bool more=false;try{more=runner.MoveNext();if(more)next=runner.Current;}catch(Exception ex){report.error=ex.ToString();break;}if(!more)break;yield return next;}
 Key();InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);InputSystem.settings=original;Destroy(test);foreach(var c in ai.nightConfigs)Destroy(c);ai.nightConfigs=originals;report.finished=true;report.passed=string.IsNullOrEmpty(report.error);System.IO.File.WriteAllText("Temp/BedroomPrototype/WindowPlayModeChecks.json",JsonUtility.ToJson(report,true));Debug.Log("Window verification "+report.passed+" "+report.error);}
